import 'package:flutter/material.dart';import 'package:intl/intl.dart';import 'package:sizer/sizer.dart';import 'package:smart_coach_new/core/utils/enums.dart';import 'package:smart_coach_new/core/utils/toast_message_utils.dart';import 'package:smart_coach_new/core/utils/utils.dart';import 'package:smart_coach_new/core/widgets/custom_button.dart';import 'package:smart_coach_new/core/widgets/custom_checkbox.dart';import 'package:smart_coach_new/core/widgets/custom_divider.dart';import 'package:smart_coach_new/features/user_management/domain/entities/pending_users_request.dart';class FilterDialog extends StatefulWidget {  final Function onTapReset;  final PendingUsersRequest? request;  const FilterDialog(      {super.key, required this.onTapReset, required this.request});  @override  State<FilterDialog> createState() => _FilterDialogState();}class _FilterDialogState extends State<FilterDialog> {  final Map<String, bool> statusOptions = {    UserApprovalStatus.pending.name: false,    UserApprovalStatus.approved.name: false,    UserApprovalStatus.rejected.name: false,  };  final Map<String, bool> organizationTypeOptions = {    OrganizationType.indianRailways.name: false,    OrganizationType.contractor.name: false,  };  DateTime? fromDate;  DateTime? toDate;  Future<void> _pickDate(BuildContext context, bool isFromDate) async {    final DateTime? picked = await showDatePicker(      context: context,      initialDate: DateTime.now(),      firstDate: DateTime(2000),      lastDate: DateTime.now(),    );    if (picked != null) {      setState(() {        if (isFromDate) {          fromDate = picked;        } else {          toDate = picked;        }      });    }  }  @override  void initState() {    super.initState();    if (widget.request != null) {      final filter = widget.request!;      // Restore status selections      if (filter.statusList != null) {        statusOptions.updateAll(              (key, _) => filter.statusList!.contains(key),        );      }      // Restore organization type selections      if (filter.organizationTypeList != null) {        organizationTypeOptions.updateAll(              (key, _) => filter.organizationTypeList!.contains(key),        );      }      // Restore fromDate      fromDate =      filter.fromDate != null ? DateTime.tryParse(filter.fromDate!) : null;      // Restore toDate      toDate = filter.toDate != null ? DateTime.tryParse(filter.toDate!) : null;    }  }  @override  Widget build(BuildContext context) {    return Dialog(      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(4.w)),      insetPadding: EdgeInsets.symmetric(horizontal: 5.w),      child: Padding(        padding: EdgeInsets.all(5.w),        child: Column(          mainAxisSize: MainAxisSize.min,          children: [            /// Header            Row(              mainAxisAlignment: MainAxisAlignment.spaceBetween,              children: [                Text(                  'Filter Options',                  style: TextStyle(                    fontWeight: FontWeight.w600,                    fontSize: 14.sp,                  ),                ),                GestureDetector(                  onTap: () => Navigator.pop(context),                  child: Icon(Icons.close, size: 18.sp),                ),              ],            ),            CustomDivider(),            _buildSectionTitle("Status"),            ...statusOptions.keys.map((key) {              return CustomCheckbox(                value: statusOptions[key],                text: key,                fontSize: 12,                onChange: (val) {                  setState(() => statusOptions[key] = val ?? false);                },              );            }),            SizedBox(height: 1.h),            _buildSectionTitle("Organization Type"),            ...organizationTypeOptions.keys.map((key) {              return CustomCheckbox(                value: organizationTypeOptions[key],                text: key,                fontSize: 12,                onChange: (val) {                  setState(() => organizationTypeOptions[key] = val ?? false);                },              );            }),            SizedBox(height: 1.h),            _buildSectionTitle("Date Range"),            SizedBox(height: 1.h),            Row(              children: [                Expanded(                  child: _buildDatePickerField(                    label: "From",                    date: fromDate,                    onTap: () => _pickDate(context, true),                  ),                ),                SizedBox(width: 2.w),                Expanded(                  child: _buildDatePickerField(                    label: "To",                    date: toDate,                    onTap: () => _pickDate(context, false),                  ),                ),              ],            ),            CustomDivider(),            Row(              mainAxisAlignment: MainAxisAlignment.end,              children: [                CustomButton(                  text: 'Reset',                  color: Color(0xFFF2F3F5),                  textColor: Colors.black,                  textSize: 12,                  padding:                  EdgeInsets.symmetric(vertical: 1.6.h, horizontal: 5.w),                  radius: 6,                  onPressed: () {                    Navigator.pop(context);                    widget.onTapReset.call();                  },                ),                SizedBox(width: 3.w),                CustomButton(                  text: 'Apply',                  padding:                  EdgeInsets.symmetric(vertical: 1.6.h, horizontal: 5.w),                  textSize: 12,                  radius: 6,                  onPressed: () {                    final List<String> selectedStatuses =                    getSelectedKeys(statusOptions);                    final List<String> selectedOrganizationTypeOptions =                    getSelectedKeys(organizationTypeOptions);                    // String? firstSelectedStatus = selectedStatuses.isNotEmpty                    //     ? selectedStatuses.first                    //     : null;                    // String? firstOrganizationType =                    //     selectedOrganizationTypeOptions.isNotEmpty                    //         ? selectedOrganizationTypeOptions.first                    //         : null;                    String? fromFormatted = Utils.getFormattedDate(fromDate, 'yyyy-MM-dd');                    String? toFormatted =                    Utils.getFormattedDate(toDate, 'yyyy-MM-dd');                    if (selectedStatuses.isEmpty &&                        selectedOrganizationTypeOptions.isEmpty &&                        fromFormatted == null &&                        toFormatted == null) {                      ToastMessageUtils.showMessage(                          context, 'No filter selected to apply');                    } else {                      PendingUsersRequest request = PendingUsersRequest(                        statusList: selectedStatuses,                        organizationTypeList: selectedOrganizationTypeOptions,                        fromDate: fromFormatted,                        toDate: toFormatted,                      );                      Navigator.pop(context, request);                    }                  },                ),              ],            ),          ],        ),      ),    );  }  Widget _buildSectionTitle(String title) {    return Align(      alignment: Alignment.centerLeft,      child: Text(        title,        style: TextStyle(          fontWeight: FontWeight.w500,          fontSize: 12.5.sp,        ),      ),    );  }  Widget _buildDatePickerField({    required String label,    required DateTime? date,    required VoidCallback onTap,  }) {    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      children: [        Text(          label,          style: TextStyle(            fontWeight: FontWeight.w500,            fontSize: 10.5.sp,            color: Colors.grey.shade700,          ),        ),        SizedBox(          height: 0.3.h,        ),        GestureDetector(          onTap: onTap,          child: Container(            padding: EdgeInsets.symmetric(horizontal: 3.w, vertical: 1.h),            decoration: BoxDecoration(              border: Border.all(color: Colors.grey.shade300),              borderRadius: BorderRadius.circular(2.w),            ),            child: Row(              children: [                Expanded(                  child: Text(                    date != null                        ? DateFormat('dd-MM-yyyy').format(date)                        : 'dd-mm-yyyy',                    style: TextStyle(                      fontSize: 12.sp,                      fontWeight: FontWeight.w500,                    ),                  ),                ),                Icon(Icons.calendar_today, size: 14.sp, color: Colors.black),              ],            ),          ),        ),      ],    );  }  List<String> getSelectedKeys(Map<String, bool> map) {    return map.entries        .where((entry) => entry.value)        .map((entry) => entry.key)        .toList();  }}